// Clean the form data and normalise the phone. The phone function is the same one as
// n8n/snippets/normalize-phone.js (rule 7) - keep them identical.
function normalizeIndianPhone(raw) {
  if (raw === null || raw === undefined) return { phone: null, valid: false };
  let digits = String(raw).replace(/\D/g, '');
  if (digits.startsWith('0091')) digits = digits.slice(4);
  else if (digits.length === 12 && digits.startsWith('91')) digits = digits.slice(2);
  else if (digits.length === 11 && digits.startsWith('0')) digits = digits.slice(1);
  const valid = /^[6-9]\d{9}$/.test(digits);
  return { phone: valid ? `+91${digits}` : null, valid };
}

const body = $json.body || {};
const noControl = (v) => String(v === null || v === undefined ? '' : v).replace(/[\u0000-\u0008\u000b-\u001f\u007f]/g, '');
const line = (v, max) => noControl(v).replace(/\s+/g, ' ').trim().slice(0, max);
const text = (v, max) => noControl(v).trim().slice(0, max);

const slug = line(body.clinic_slug, 40).toLowerCase();
const clinic_slug = /^[a-z0-9-]{2,40}$/.test(slug) ? slug : '';
const name = line(body.name, 100);
const { phone, valid } = normalizeIndianPhone(body.phone);
const honeypot = line(body.website, 200);   // hidden field: humans leave it empty, bots fill it

let skip_reason = '';
if (honeypot) skip_reason = 'honeypot filled';
else if (!name) skip_reason = 'missing name';
else if (!valid) skip_reason = 'invalid phone';

return {
  json: {
    grist_base_url: String($json.grist_base_url || '').replace(/\/+$/, ''),
    registry_doc_id: String($json.registry_doc_id || '').trim(),
    clinic_slug,
    name,
    phone,
    phone_raw: line(body.phone, 30),
    enquiry: text(body.enquiry, 1000),
    page_url: line(body.page_url, 500),
    utm_campaign: line(body.utm_campaign, 100),
    input_ok: skip_reason === '',
    skip_reason,
  },
};

const ctx = $('W1 – Prepare lead').first().json;
const rec = ($json.records || [])[0];
const f = rec ? rec.fields || {} : {};
const found = !!(
rec &&
ctx.clinic_slug &&
f.Clinic_Slug === ctx.clinic_slug &&
(f.Active === true || f.Active === 1 || String(f.Active).toLowerCase() === 'true') &&
f.Grist_Doc_ID
);
return {
  json: {
    ...ctx,
    clinic_found: found,
    doc_id: found ? String(f.Grist_Doc_ID).trim() : '',
    clinic_name: found ? String(f.Clinic_Name || '') : '',
    wa_phone_number_id: found ? String(f.WA_Phone_Number_ID || '') : '',
  },
};

const ctx = $('W1 – Resolve clinic').first().json;
const rec = $json.records[0];
const old = String(rec.fields.Enquiry || '');
const today = new Date(Date.now() + 5.5 * 3600 * 1000).toISOString().slice(0, 10);   // IST date

const fields = {};
if (ctx.enquiry && !old.includes(ctx.enquiry)) {
  fields.Enquiry = old ? `${old}\n---\n${today}: ${ctx.enquiry}` : ctx.enquiry;
}
if (ctx.page_url && ctx.page_url !== String(rec.fields.Page_URL || '')) fields.Page_URL =    ctx.page_url;
if (ctx.utm_campaign && ctx.utm_campaign !== String(rec.fields.UTM_Campaign || ''))    fields.UTM_Campaign = ctx.utm_campaign;

const has_changes = Object.keys(fields).length > 0;
return {
  json: {
    ...ctx,
    action: 'updated',
    lead_id: rec.fields.Lead_ID || `row ${rec.id}`,
    has_changes,
    skip_reason: has_changes ? '' : 'duplicate submission',
    patch: { records: [{ id: rec.id, fields }] },
  },
};

const ctx = $('W1 – Resolve clinic').first().json;
const now = Date.now();
const ymd = new Date(now + 5.5 * 3600 * 1000).toISOString().slice(0, 10).replace(/-/g, '');   // IST date
const prefix = `L-${ymd}-`;

let max = 0;
for (const r of $json.records || []) {
  const id = String((r.fields || {}).Lead_id || '');
  if (id.startsWith(prefix)) max = Math.max(max, parseInt(id.slice(prefix.length), 10) || 0);
}
const lead_id = prefix + String(max + 1).padStart(4, '0');

const fields = {
  Lead_id: lead_id,
  Created_At: Math.floor(now / 1000),   // Grist DateTime = epoch seconds
  Name: ctx.name,
  Phone: ctx.phone,
  Source: 'Website',
  Page_URL: ctx.page_url,
  UTM_Campaign: ctx.utm_campaign,
  Enquiry: ctx.enquiry,
  Status: 'New',
};
return { json: { ...ctx, action: 'created', lead_id, create: { records: [{ fields }] } } };

const from = (name) => {
  try { return $(name).first().json; } catch (e) { return null; }   // throws if that branch did not run
};
const ctx = from('W1 – Build update') || from('W1 – Build new lead');

const quote = ctx.enquiry ? ` - "${ctx.enquiry.slice(0, 200)}"` : '';
const what = ctx.action === 'created' ? 'New website lead' : 'Existing lead enquired again';
const staff_alert_text = `${what} (${ctx.clinic_name || ctx.clinic_slug}): ${ctx.name}, ${ctx.phone}${quote}. ${ctx.lead_id}.`;

// STUB: nothing is sent. The real WhatsApp alert comes in a later slice and must follow rules 4 and 5
// (sent flag, Opted_Out / Automation_Paused, quiet hours 21:00-08:00 IST, TEST_MODE).
return {
  json: {
    ...ctx,
    staff_alert_text,
    staff_alert_sent: false,
    log: {
      Workflow: 'W1-website-lead',
      Record: `${ctx.lead_id} (${ctx.action})`,
      Outcome: 'ok',
      Error: '',
      At: Math.floor(Date.now() / 1000),
    },
  },
};

return {
  json: {
    ...$json,
    log: {
      Workflow: 'W1-website-lead',
      Record: $json.phone || $json.phone_raw || '',
      Outcome: 'skipped',
      Error: $json.skip_reason || 'unknown',
      At: Math.floor(Date.now() / 1000),
    },
  },
};

const cfg = $('W3 – Config').first().json;
const base = String(cfg.grist_base_url || '').replace(/\/+$/, '');

const clinics = ($input.first().json.records || []).filter(
  (r) =>
    r.fields &&
    String(r.fields.Active).toUpperCase() === 'TRUE' &&
    String(r.fields.Grist_Doc_ID || '').trim()
);

return clinics.map((r) => ({
  json: {
    grist_base_url: base,
    doc_id: String(r.fields.Grist_Doc_ID).trim(),
    clinic_slug: String(r.fields.Clinic_Slug || ''),
    registry_clinic_name: String(r.fields.Clinic_Name || ''),
    wa_phone_number_id: String(r.fields.WA_Phone_Number_ID || '').trim(),
  },
  pairedItem: { item: 0 },
}));

// Pasted from n8n/snippets/clinic-hours.js - keep identical.
const DAY_INDEX = { sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6 };

function parseClock(text) {
  const m = String(text === null || text === undefined ? '' : text).trim().match(/^(\d{1,2})(?:[:.](\d{2}))?\s*(a\.?m\.?|p\.?m\.?)?$/i);
  if (!m) return null;
  let h = parseInt(m[1], 10);
  const min = m[2] ? parseInt(m[2], 10) : 0;
  const meridiem = m[3] ? m[3][0].toLowerCase() : '';
  if (min > 59) return null;
  if (meridiem) {
    if (h < 1 || h > 12) return null;
    h = (h % 12) + (meridiem === 'p' ? 12 : 0);
  } else if (h > 24 || (h === 24 && min > 0)) {
    return null;
  }
  return h * 60 + min;   // minutes after midnight
}

function parseDays(text) {
  const s = String(text === null || text === undefined ? '' : text).toLowerCase().replace(/[–—]/g, '-').replace(/\s+to\s+/g, '-').replace(/\s+(and|&)\s+/g, ',').trim();
  if (!s) return null;
  if (/^(daily|every ?day|all days|7 ?days?)$/.test(s)) return [0, 1, 2, 3, 4, 5, 6];
  const dayOf = (t) => {
    const x = t.trim();
    return /^(sun|mon|tue|wed|thu|fri|sat)[a-z]*\.?$/.test(x) ? DAY_INDEX[x.slice(0, 3)] : undefined;
  };
  const days = new Set();
  for (const token of s.split(/[,;/]+/)) {
    if (!token.trim()) continue;
    if (token.includes('-')) {
      const [a, b] = token.split('-').map(dayOf);
      if (a === undefined || b === undefined) return null;
      for (let d = a; ; d = (d + 1) % 7) { days.add(d); if (d === b) break; }
    } else {
      const d = dayOf(token);
      if (d === undefined) return null;
      days.add(d);
    }
  }
  return days.size ? [...days].sort() : null;   // 0 = Sunday
}

function isOpenNow(i) {
  if (!Number.isFinite(i.now_ms)) return { open: false, source: 'default' };
  let open = parseClock(i.open_time);
  let close = parseClock(i.close_time);
  let days = parseDays(i.working_days);
  let source = 'settings';
  if (open === null || close === null || close <= open) { open = 8 * 60; close = 21 * 60; source = 'default'; }
  if (days === null) { days = [0, 1, 2, 3, 4, 5, 6]; source = 'default'; }
  const t = new Date(i.now_ms + 5.5 * 3600 * 1000);   // IST wall-clock via UTC getters
  const minutes = t.getUTCHours() * 60 + t.getUTCMinutes();
  return { open: days.includes(t.getUTCDay()) && minutes >= open && minutes < close, source };
}

  const clinics = $('W3 – Split clinics').all();
  return $input.all().map((item, i) => {
    const s = {};
    for (const r of item.json.records || []) {
      const f = r.fields || {};
      if (f.Key) s[String(f.Key).trim()] = f.Value;
    }
    const hours = isOpenNow({ open_time: s.open_time, close_time: s.close_time, working_days: s.working_days, now_ms: Date.now() });
    return {
      json: {
        ...clinics[i].json,
        clinic_name: String(s.clinic_name || clinics[i].json.registry_clinic_name || ''),
        owner_phone: s.owner_phone,
        test_mode: s.TEST_MODE,         // raw text; a missing row means TEST_MODE is ON (see send-guard.js)
        test_phone: s.TEST_PHONE,
        open_now: hours.open,
        hours_source: hours.source,      // 'default' = open_time / close_time / working_days missing or unreadable
      },
      pairedItem: { item: i },
    };
  });

const cfg = $('W3 – Config').first().json;
const nowMs = Date.now();
const minAge = Number(cfg.new_for_minutes);           // waiting at least this long ...
const maxAge = Number(cfg.max_age_hours) * 60;        // ... but not an old backlog
const cap = Number(cfg.max_alerts_per_run);           // per clinic per run, oldest first
const clinics = $('W3 – Add settings').all();
const out = [];

$input.all().forEach((item, i) => {
  const base = clinics[i].json;
  // if (!base.open_now) return;                         // outside clinic hours: leave everything for the next run

  const due = (item.json.records || [])
    .filter((r) => {
      const f = r.fields || {};
      if (f.Status !== 'New' || f.Escalated || typeof f.Created_At !== 'number') return false;
      const minutes = (nowMs - f.Created_At * 1000) / 60000;
      return minutes >= minAge && minutes <= maxAge;
    })
    .sort((a, b) => a.fields.Created_At - b.fields.Created_At)
    .slice(0, cap);

  for (const r of due) {
    const f = r.fields;
    out.push({
      json: {
        ...base,
        lead_row_id: r.id,
        lead_id: f.Lead_id || `row ${r.id}`,
        lead_name: String(f.Name || ''),
        lead_phone: String(f.Phone || ''),
        source: String(f.Source || ''),
        enquiry: String(f.Enquiry || '').replace(/\s+/g, ' ').trim().slice(0, 200),
        waiting_minutes: Math.floor((nowMs - f.Created_At * 1000) / 60000),
        escalated: !!f.Escalated,
      },
      pairedItem: { item: i },
    });
  }
});
return out;

// Pasted from n8n/snippets/normalize-phone.js and n8n/snippets/send-guard.js - keep identical.
function normalizeIndianPhone(raw) {
  if (raw === null || raw === undefined) return { phone: null, valid: false };
  let digits = String(raw).replace(/\D/g, '');          // keep digits only
  if (digits.startsWith('0091')) digits = digits.slice(4);
  else if (digits.length === 12 && digits.startsWith('91')) digits = digits.slice(2);
  else if (digits.length === 11 && digits.startsWith('0')) digits = digits.slice(1);
  const valid = /^[6-9]\d{9}$/.test(digits);            // Indian mobiles start 6-9
  return { phone: valid ? `+91${digits}` : null, valid };
}

function isTestMode(value) {
  const v = String(value === null || value === undefined ? '' : value).trim().toLowerCase();
  return !['false', '0', 'no', 'off'].includes(v);   // anything else, including a missing row, means ON (fail safe)
}

function inQuietHours(nowMs) {
  if (!Number.isFinite(nowMs)) return true;           // no clock, no send
  const hourIST = new Date(nowMs + 5.5 * 3600 * 1000).getUTCHours();
  return hourIST >= 21 || hourIST < 8;
}

function decideSend(i) {
  const testMode = isTestMode(i.test_mode);
  const skip = (reason) => ({ send: false, to: null, reason, test_mode: testMode });

  if (i.flag_value) return skip('already sent');
  if (i.opted_out) return skip('opted out');
  if (i.kind !== 'transactional' && i.automation_paused) return skip('automation paused');
  if (inQuietHours(i.now_ms)) return skip('quiet hours');

  const to = testMode ? i.test_phone : i.patient_phone;
  if (!to) return skip(testMode ? 'test mode on but TEST_PHONE is missing or invalid' : 'no valid patient phone');
  return { send: true, to, reason: testMode ? 'test mode: sent to TEST_PHONE' : 'ok', test_mode: testMode };
}

  const { phone: owner_phone } = normalizeIndianPhone($json.owner_phone);
  const { phone: test_phone } = normalizeIndianPhone($json.test_phone);
  const decision = decideSend({
    kind: 'transactional',
    flag_value: $json.escalated ? 1 : null,    // the Escalated toggle is this alert's "sent" flag (rule 4)
    opted_out: false,
    automation_paused: false,
    patient_phone: owner_phone,                // "patient_phone" is just the guard's name for the recipient
    test_mode: $json.test_mode,
    test_phone,
    now_ms: Date.now(),
  });
  return { json: { ...$json, decision, send: decision.send } };

const now = Math.floor(Date.now() / 1000);
return {
  json: {
    ...$json,
    patch: { records: [{ id: $json.lead_row_id, fields: { Escalated: true } }] },
    log: { Workflow: 'W3-speed-to-lead', Record: `${$json.lead_id} (escalated)`, Outcome: 'ok', Error: '', At: now },
  },
};

const item = $json;

const name = item.lead_name || item.name || item.patient_name || 'New lead';
const phone = item.lead_phone || item.phone || '';
const clinic = item.clinic_name || 'Clinic';

const template = 'hello_world';

const message_text =
  `New lead: ${name} (${phone}) has submitted an enquiry for ${clinic}.`;

return {
  json: {
    ...item,

    source_workflow: 'W3-speed-to-lead',
    audience: 'staff',

    template,

    template_params: {
    clinic_name: clinic,
    lead_name: name,
    lead_phone: phone,
    enquiry: item.enquiry || '',
    },

    message_text,

    wa_phone_number_id:
      item.wa_phone_number_id ||
      item.WA_Phone_Number_ID ||
      '',

    decision: item.decision || {
      send: Boolean(item.send),
      to: item.decision?.to || '',
      reason: 'W3 speed-to-lead',
      test_mode: Boolean(item.test_mode),
    },

    send: Boolean(item.send),
  },
};

// Pasted from n8n/snippets/normalize-phone.js and n8n/snippets/hmac-sha256.js - keep identical.
function normalizeIndianPhone(raw) {
  if (raw === null || raw === undefined) return { phone: null, valid: false };
  let digits = String(raw).replace(/\D/g, '');          // keep digits only
  if (digits.startsWith('0091')) digits = digits.slice(4);
  else if (digits.length === 12 && digits.startsWith('91')) digits = digits.slice(2);
  else if (digits.length === 11 && digits.startsWith('0')) digits = digits.slice(1);
  const valid = /^[6-9]\d{9}$/.test(digits);            // Indian mobiles start 6-9
  return { phone: valid ? `+91${digits}` : null, valid };
}

function utf8Bytes(str) {
  const out = [];
  for (const ch of String(str)) {
    const c = ch.codePointAt(0);
    if (c < 0x80) out.push(c);
    else if (c < 0x800) out.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    else if (c < 0x10000) out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    else out.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
  }
  return out;
}

function sha256Bytes(bytes) {
  const K = [
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  ];
  const H = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  const rotr = (x, n) => (x >>> n) | (x << (32 - n));

  const msg = bytes.slice();
  const bitLen = bytes.length * 8;
  msg.push(0x80);
  while (msg.length % 64 !== 56) msg.push(0);
  const hi = Math.floor(bitLen / 0x100000000);
  const lo = bitLen >>> 0;
  for (const w of [hi, lo]) msg.push((w >>> 24) & 255, (w >>> 16) & 255, (w >>> 8) & 255, w & 255);

  const w = new Array(64);
  for (let off = 0; off < msg.length; off += 64) {
    for (let i = 0; i < 16; i++) w[i] = ((msg[off + 4 * i] << 24) | (msg[off + 4 * i + 1] << 16) | (msg[off + 4 * i + 2] << 8) | msg[off + 4 * i + 3]) >>> 0;
    for (let i = 16; i < 64; i++) {
      const s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >>> 3);
      const s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >>> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) >>> 0;
    }
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const t1 = (h + S1 + ch + K[i] + w[i]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const t2 = (S0 + maj) >>> 0;
      h = g; g = f; f = e; e = (d + t1) >>> 0; d = c; c = b; b = a; a = (t1 + t2) >>> 0;
    }
    [a, b, c, d, e, f, g, h].forEach((v, i) => { H[i] = (H[i] + v) >>> 0; });
  }
  const out = [];
  for (const v of H) out.push((v >>> 24) & 255, (v >>> 16) & 255, (v >>> 8) & 255, v & 255);
  return out;
}

function hmacSha256Hex(key, message) {
  let k = utf8Bytes(key);
  if (k.length > 64) k = sha256Bytes(k);
  while (k.length < 64) k.push(0);
  const inner = sha256Bytes(k.map((b) => b ^ 0x36).concat(utf8Bytes(message)));
  const mac = sha256Bytes(k.map((b) => b ^ 0x5c).concat(inner));
  return mac.map((b) => b.toString(16).padStart(2, '0')).join('');
}

function safeEqual(a, b) {
  a = String(a); b = String(b);
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}

  const reject = (reason) => ({ json: { route: 'reject', reject_reason: reason } });
  const headers = $json.headers || {};
  const body = $json.body;

  // 1. Is it really Cal.com? It signs JSON.stringify(body) with the webhook secret (HMAC-SHA256, hex) in
  //    X-Cal-Signature-256. With no secret set, Cal.com sends the text "no-secret-provided".
  if ($json.require_signature !== false) {
    const secret = String($json.cal_webhook_secret || '');
    const sig = String(headers['x-cal-signature-256'] || '').trim().toLowerCase();
    if (!secret || secret.startsWith('REPLACE_')) return reject('Cal.com webhook secret is not set in the Config node');
    if (!sig || sig === 'no-secret-provided') return reject('unsigned request: set the same Secret in the Cal.com webhook');
    if (!body || typeof body !== 'object' || !safeEqual(hmacSha256Hex(secret, JSON.stringify(body)), sig)) return reject('bad signature');
  }
  if (!body || typeof body !== 'object') return reject('empty body');

  // 2. Which event? Others (ping, meeting started/ended, ...) are ignored without an alert.
  const event = String(body.triggerEvent || '');
  if (!['BOOKING_CREATED', 'BOOKING_RESCHEDULED', 'BOOKING_CANCELLED'].includes(event)) return { json: { route: 'ignore', event } };
  const p = body.payload || {};

  // 3. Which clinic? The Cal.com webhook URL ends in ?clinic=<Clinic_Slug>.
  const slug = String(($json.query || {}).clinic || '').trim().toLowerCase();
  if (!/^[a-z0-9-]{2,40}$/.test(slug)) return reject('missing or invalid ?clinic= in the webhook URL');

  // 4. Booking fields.
  const uid = String(p.uid || '').trim();
  if (!uid) return reject('booking has no uid');
  const text = (v, max) => String(v === null || v === undefined ? '' : v).replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
  const attendee = (Array.isArray(p.attendees) && p.attendees[0]) || {};
  const resp = p.responses && typeof p.responses === 'object' ? p.responses : {};

