  if (!Number.isFinite(nowMs)) return true;           // no clock, no send
  const hourIST = new Date(nowMs + 5.5 * 3600 * 1000).getUTCHours();
  return hourIST >= 21 || hourIST < 8;
}

const WA_TEMPLATES = {
  hello_world: { language: 'en_US', params: [] },          // Meta's sample template on the test number
  booking_confirmation: { params: ['name', 'service', 'clinic_name', 'date', 'time'] },
  reminder_24h: { params: ['name', 'service', 'clinic_name', 'date', 'time'] },
  reminder_2h: { params: ['name', 'service', 'clinic_name', 'time'] },
  noshow_rebook: { params: ['name', 'service', 'clinic_name', 'date', 'booking_link'] },
  followup_day2: { params: ['name', 'clinic_name', 'booking_link'] },
  new_lead_staff_alert: { params: ['clinic_name', 'lead_name', 'lead_phone', { key: 'enquiry', fallback: '(no message)' }] },
  lead_escalation: { params: ['clinic_name', 'lead_name', 'lead_phone', 'waiting_minutes'] },
  human_handoff_alert: { params: ['clinic_name', 'lead_name', 'lead_phone', { key: 'reason', fallback: '(see the Grist inbox)' }] },
  outcome_check: { params: ['name', 'clinic_name', { key: 'service', fallback: 'visit' }] },                    // W7
  review_request: { params: ['name', 'clinic_name', 'review_link'] },                                          // W8
  weekly_owner_report: { params: ['clinic_name', 'week', 'summary', { key: 'action', fallback: 'see the full report in Grist' }] },   // W9
};

// Free-text replies (message_type 'text', from W13) are only allowed inside WhatsApp's 24-hour customer-service
// window, i.e. within 24 h of the patient's last message (last_inbound_at). A 5-minute margin keeps clock drift safe.
const WA_TEXT_WINDOW_MS = 24 * 3600 * 1000 - 5 * 60 * 1000;

// Short hints for the Meta error codes we are most likely to meet (shown in send_error).
const WA_HINTS = {
  190: 'access token invalid or expired - put a permanent System User token in the "WhatsApp Cloud API" credential',
  10: 'token lacks permission - give the System User whatsapp_business_messaging',
  200: 'token lacks permission - give the System User whatsapp_business_messaging',
  100: 'invalid parameter - check wa_phone_number_id and the template',
  131030: "recipient is not in the test number's allowed list - add it in Meta > WhatsApp > API Setup",
  131026: 'message undeliverable (number not on WhatsApp?)',
  131047: 'outside the 24h window - only templates can be sent',
  131056: 'too many messages to this number - try later',
  130429: 'rate limit hit - try later',
  132000: 'number of template variables does not match the approved template',
  132001: 'template not found in this language - check the name and language code',
  132005: 'template text too long after filling the variables',
  132007: 'template content policy violation',
  132012: 'template variable format does not match',
  133010: 'phone number not registered with the Cloud API',
  131031: 'WhatsApp account locked',
  368: 'temporarily blocked for policy violations',
};

// Meta: a variable may not contain new-lines, tabs or runs of spaces.
function waCleanParam(v) {
  return String(v === null || v === undefined ? '' : v).replace(/\s+/g, ' ').trim().slice(0, 250);
}

// Decide whether to call Meta, and build the request. Never throws.
// input: the caller's item (decision, template, template_params, wa_phone_number_id, ...); cfg: W12 Config.
function waPrepare(input, cfg, nowMs, h) {
  const stop = (send_status, send_error) => ({ call_meta: false, send_status, send_error });
  const d = input && input.decision;
  if (!d || d.send !== true) return stop('not_requested', d && d.reason ? `guard said no: ${d.reason}` : 'no send decision from the caller');

  const mode = String(cfg.send_mode || '').trim().toLowerCase();
  if (mode !== 'allowlist' && mode !== 'live') return stop('blocked', `W12 send_mode is "${cfg.send_mode}" - only "allowlist" or "live" send`);

  // 1. Is the message itself sendable? (reported even while testing in allowlist mode or at night)
  const to = h.normalizeIndianPhone(d.to).phone;
  if (!to) return stop('invalid', 'decision.to is not a valid Indian mobile number');
  const version = String(cfg.graph_api_version || '').trim();
  if (!/^v\d+\.\d+$/.test(version)) return stop('invalid', 'graph_api_version is not set in the W12 Config node (e.g. v23.0 - copy it from Meta API Setup)');
  const phoneId = String(input.wa_phone_number_id || '').trim();
  if (!/^\d{5,25}$/.test(phoneId)) return stop('invalid', 'wa_phone_number_id is missing or not a number (Agency Registry > Clinics > WA_Phone_Number_ID)');
  const isText = input.message_type === 'text';
  let tpl = null;
  let textBody = '';
  const params = [];
  if (isText) {
    textBody = String(input.text_body === null || input.text_body === undefined ? '' : input.text_body).replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '').trim().slice(0, 4096);
    if (!textBody) return stop('invalid', 'text message: text_body is empty');
    const last = Number(input.last_inbound_at);
    if (!Number.isFinite(last) || last <= 0) return stop('invalid', 'text message: last_inbound_at (the patient\'s last message, epoch seconds) is missing');
    if (nowMs - last * 1000 > WA_TEXT_WINDOW_MS) return stop('blocked', 'outside the 24-hour WhatsApp window: only an approved template may be sent');
  } else {
    tpl = WA_TEMPLATES[input.template];
    if (!tpl) return stop('invalid', `unknown template "${input.template}" - add it to WA_TEMPLATES in W12`);
    const values = input.template_params || {};
    for (const spec of tpl.params) {
      const key = typeof spec === 'string' ? spec : spec.key;
      let v = waCleanParam(values[key]);
      if (!v && typeof spec === 'object') v = spec.fallback;
      if (!v) return stop('invalid', `template ${input.template}: variable "${key}" is empty`);
      params.push(v);
    }
  }

  // 2. May it go out now, to this number?
  if (mode === 'allowlist') {
    const allowed = String(cfg.allowlist || '').split(/[,;]+/).map((x) => h.normalizeIndianPhone(x).phone).filter(Boolean);
    if (!allowed.includes(to)) return stop('blocked', `${to} is not in the W12 allowlist (send_mode = allowlist)`);
  }
  if (h.inQuietHours(nowMs)) return stop('blocked', 'quiet hours (21:00-08:00 IST)');

  if (isText) {
    return {
      call_meta: true,
      send_status: 'pending',
      send_error: '',
      to,
      meta_url: `https://graph.facebook.com/${version}/${phoneId}/messages`,
      meta_request: { messaging_product: 'whatsapp', recipient_type: 'individual', to: to.slice(1), type: 'text', text: { preview_url: /https?:\/\//i.test(textBody), body: textBody } },
    };
  }
  const template = { name: input.template, language: { code: String(input.template_language || tpl.language || cfg.default_language || 'en') } };
  if (params.length) template.components = [{ type: 'body', parameters: params.map((text) => ({ type: 'text', text })) }];
  return {
    call_meta: true,
    send_status: 'pending',
    send_error: '',
    to,
    meta_url: `https://graph.facebook.com/${version}/${phoneId}/messages`,
    meta_request: { messaging_product: 'whatsapp', recipient_type: 'individual', to: to.slice(1), type: 'template', template },
  };
}

// Turn the HTTP node output (fullResponse + neverError, or a "continue on error" item) into a result.
//   accepted  Meta returned a message id                  -> sent: true
//   rejected  Meta refused, or the request never left     -> sent: false (safe to try again later)
//   uncertain the request left but no clear answer came   -> sent: cfg.uncertain_counts_as_sent (default true:
//             rather miss one message than send it twice, CLAUDE.md rule 4)
function waClassify(resp, cfg) {
  const uncertainSent = cfg.uncertain_counts_as_sent !== false;
  const result = (send_status, extra) => Object.assign({
    send_status,
    sent: send_status === 'accepted' || (send_status === 'uncertain' && uncertainSent),
    wa_message_id: '',
    send_error: '',
    send_error_code: null,
    send_http_status: null,
  }, extra);

  if (resp && typeof resp.statusCode === 'number') {
    let body = resp.body;
    if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
    body = body || {};
    const id = body.messages && body.messages[0] && body.messages[0].id;
    if (resp.statusCode >= 200 && resp.statusCode < 300) {
      return id
        ? result('accepted', { wa_message_id: String(id), send_http_status: resp.statusCode })
        : result('uncertain', { send_error: 'Meta answered without a message id', send_http_status: resp.statusCode });
    }
    const e = body.error || {};
    const code = e.code !== undefined && e.code !== null ? Number(e.code) : null;
    const detail = (e.error_data && e.error_data.details) || e.message || `HTTP ${resp.statusCode}`;
    const hint = code !== null && WA_HINTS[code] ? ` (${WA_HINTS[code]})` : '';
    return result('rejected', { send_error_code: code, send_http_status: resp.statusCode, send_error: `${code !== null ? code + ': ' : ''}${detail}${hint}`.slice(0, 500) });
  }

  // n8n's "continue on error" item: { error: '...' } or { error: { message, description, code, ... } }. n8n also
  // rewrites network errors into friendly text, so match both the raw codes and n8n's wording.
  const err = resp && resp.error;
  const msg = String((err && (err.message || err.description)) || (typeof err === 'string' ? err : '') || 'no reply from Meta');
  const haystack = typeof err === 'string' ? err : JSON.stringify(err || {});
  if (/ENOTFOUND|EAI_AGAIN|ECONNREFUSED|EHOSTUNREACH|ENETUNREACH|certificate|self[- ]signed|refused the connection|DNS server returned an error/i.test(haystack)) {
    return result('rejected', { send_error: `not sent - could not reach Meta: ${msg}`.slice(0, 500) });
  }
  return result('uncertain', { send_error: `no clear answer from Meta (it may or may not have been sent): ${msg}`.slice(0, 500) });
}

// Should this send be written to the Grist Inbox (Conversations + Messages)? Only patient messages that
// actually reached the point of calling Meta. The conversation is the PATIENT's (lead_phone), even when
// TEST_MODE sent the message to TEST_PHONE. A message that already has its own Messages row (W10 staff reply:
// inbox_row_id) is not written again; its caller updates that row.
function waInboxPlan(input, cfg, res, h) {
  const patient_phone = h.normalizeIndianPhone(input.lead_phone || input.patient_phone).phone;
  const attempted = ['accepted', 'uncertain', 'rejected'].includes(res.send_status);
  const own = Number(input.inbox_row_id) > 0;
  const log = cfg.log_to_inbox !== false && input.audience === 'patient' && attempted && !own && !!patient_phone && !!input.grist_base_url && !!input.doc_id;
  return { log, patient_phone };
}

// The Messages row. Send stays false: W10 sends rows whose Send is ticked, and this one is already out.
function waInboxRow(input, res, nowSec) {
  const d = input.decision || {};
  const via = d.test_mode ? ` (TEST_MODE: sent to ${d.to})` : '';
  return {
    Direction: 'Out',
    Body: String(input.message_text || input.text_body || `[template ${input.template}]`).slice(0, 2000),
    Template: input.message_type === 'text' ? '' : String(input.template || ''),
    Sent_By: `${input.source_workflow || 'W12'}${via}`.slice(0, 200),
    WA_Message_ID: res.wa_message_id || '',
    Status: res.send_status === 'rejected' ? 'failed' : 'queued',
    Send: false,
    Created_At: nowSec,
  };
}

  const p = $('W12 – Prepare request').first().json;
  const res = waClassify($json, p.cfg);
  const inbox = waInboxPlan(p.input, p.cfg, res, { normalizeIndianPhone, inQuietHours });
  const inbox_row = inbox.log ? waInboxRow(p.input, res, Math.floor(Date.now() / 1000)) : null;   // built here: this node has the helpers
  return { json: { ...p, res, log_inbox: inbox.log, patient_phone: inbox.patient_phone, inbox_row } };

const p = $('W12 – Read reply').first().json;
const rec = !$json.error && Array.isArray($json.records) ? $json.records[0] : null;
const leadId = Number(p.input.lead_row_id);
const conversation_fields = { Phone: p.patient_phone };
if (Number.isInteger(leadId) && leadId > 0) conversation_fields.Lead = leadId;
return {
  json: {
    ...p,
    conversation_id: rec ? rec.id : 0,
    create_conversation: !rec,
    conversation_fields,
  },
};

const from = (name) => {
  try { return $(name).first().json; } catch (e) { return null; }   // throws if that branch did not run
};
const p = from('W12 – Read reply') || from('W12 – Prepare request');
const res = p.res || {
  send_status: p.prep.send_status, sent: false, wa_message_id: '', send_error: p.prep.send_error, send_error_code: null, send_http_status: null,
};
const added = from('W12 – Add message');
const inbox_logged = !!(added && !added.error && Array.isArray(added.records) && added.records.length);
const inbox_error = added && added.error ? String(added.error.message || added.error) : '';
return {
  json: {
    ...p.input,
    sent: res.sent === true,
    send_status: res.send_status,
    wa_message_id: res.wa_message_id || '',
    send_error: res.send_error || '',
    send_error_code: res.send_error_code === undefined ? null : res.send_error_code,
    send_http_status: res.send_http_status === undefined ? null : res.send_http_status,
    inbox_logged,
    inbox_error,
  },
};

// Meta webhook verification (GET). Meta sends hub.mode, hub.verify_token and hub.challenge as query parameters.
// The expected token comes from the "W2 – Verify Config" node (a placeholder you fill in); it is never written in this code
// and it is NOT copied into this node's output.
const q = $json.query || {};
const pick = (k) => {
  const v = q['hub.' + k] !== undefined ? q['hub.' + k] : (q.hub && q.hub[k]);   // n8n keeps "hub.mode" as one key; a nested hub{} is handled too
  return Array.isArray(v) ? String(v[0]) : (v === undefined || v === null ? '' : String(v));
};
const mode = pick('mode');
const sent = pick('verify_token');
const challenge = pick('challenge');
const want = String($json.meta_verify_token || '');
const PLACEHOLDER = 'PASTE_META_WEBHOOK_VERIFY_TOKEN';
const same = (a, b) => {                                  // compares every character, so the time taken does not reveal how much matched
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
};

let ok = false;
let status = 403;
let reason = '';
if (!want || want === PLACEHOLDER) reason = 'verify token is not configured (fill it in the "W2 – Verify Config" node)';
else if (mode !== 'subscribe') reason = 'hub.mode is not "subscribe"';
else if (!same(sent, want)) reason = 'verify token does not match';
else if (!/^[0-9A-Za-z_.~-]{1,128}$/.test(challenge)) { reason = 'hub.challenge is missing or malformed'; status = 400; }
else ok = true;

return { json: { ok, status_code: ok ? 200 : status, challenge: ok ? challenge : '', reason } };

// Manual test data for W2. Click "Execute workflow" on "W2 – Manual Test": every case below goes through the normal path
// (Config -> Parse -> clinic -> duplicate check -> lead -> conversation -> message -> Run_Log) WITHOUT Meta and without answering a webhook.
// SAFE FAKE DATA ONLY: the 91900000001x numbers and the display number 15550000000 are made up. Never paste a real patient's number here.
//
// Before the first run create ONE test lead in the demo-clinic CRM:  Phone +919000000011,  Name "W2 Test Existing".
// Afterwards delete the rows the tests created (leads, conversations, messages, Run_Log) by hand in Grist: W2 never deletes anything.
const DEMO_PHONE_NUMBER_ID = '123456789012345';   // WA_Phone_Number_ID of demo-clinic in the Agency Registry
const ONLY = '';              // a case name (e.g. 'new-patient') runs just that one; '' runs all of them
const PASTED_PAYLOAD = null;  // or paste ONE Meta POST body here (a JSON object) to run only that payload
const stamp = Date.now();     // makes the message ids unique for every run of this node (the duplicate case reuses one id on purpose)
const EXISTING = '919000000011';
const NEW_PATIENT = '919000000012';

const meta = (pid, name, from, message) => ({
  object: 'whatsapp_business_account',
  entry: [{ id: 'TEST_WABA_ID', changes: [{ field: 'messages', value: {
    messaging_product: 'whatsapp',
    metadata: { display_phone_number: '15550000000', phone_number_id: pid },
    contacts: name === null ? [] : [{ profile: { name }, wa_id: from }],
    messages: [message],
  } }] }],
});
const ts = String(Math.floor(stamp / 1000));
const text = (from, id, body) => ({ from, id, timestamp: ts, type: 'text', text: { body } });

const cases = [
  { name: 'existing-patient', expect: 'existing lead: NO new lead; 1 new message; conversation updated (Unread +1); Run_Log ok',
    body: meta(DEMO_PHONE_NUMBER_ID, 'W2 Test Existing', EXISTING, text(EXISTING, `wamid.W2TEST.${stamp}.existing`, 'Hello, I would like to ask about my knee.')) },
  { name: 'new-patient', expect: 'NEW lead (Source WhatsApp, Status New, Lead_id L-YYYYMMDD-NNNN) + conversation + message; Run_Log ok; staff alert prepared (not sent)',
    body: meta(DEMO_PHONE_NUMBER_ID, 'W2 Test New', NEW_PATIENT, text(NEW_PATIENT, `wamid.W2TEST.${stamp}.new`, 'Hi, do you treat back pain?')) },
  { name: 'duplicate-message-first', expect: 'stored once',
    body: meta(DEMO_PHONE_NUMBER_ID, 'W2 Test Existing', EXISTING, text(EXISTING, `wamid.W2TEST.${stamp}.dup`, 'Duplicate delivery test')) },
  { name: 'duplicate-message-second', expect: 'SAME message id again: nothing created, Unread not increased, Run_Log skipped (duplicate WA_Message_ID)',
    body: meta(DEMO_PHONE_NUMBER_ID, 'W2 Test Existing', EXISTING, text(EXISTING, `wamid.W2TEST.${stamp}.dup`, 'Duplicate delivery test')) },
  { name: 'unknown-phone-number-id', expect: 'stops at "W2 – Clinic Rejected" (unknown phone_number_id); nothing written',
    body: meta('000000000000000', 'W2 Test Existing', EXISTING, text(EXISTING, `wamid.W2TEST.${stamp}.unknown`, 'Unknown clinic test')) },
  { name: 'invalid-payload', expect: 'Parse says kind = invalid; nothing else runs',
    body: { hello: 'this is not a Meta webhook body' } },
  { name: 'non-text-image', expect: 'no crash; Body = "[WhatsApp image received]: photo of my knee"; Enquiry untouched',
    body: meta(DEMO_PHONE_NUMBER_ID, 'W2 Test Existing', EXISTING, { from: EXISTING, id: `wamid.W2TEST.${stamp}.image`, timestamp: ts, type: 'image', image: { id: 'TEST_MEDIA_ID', mime_type: 'image/jpeg', sha256: 'test', caption: 'photo of my knee' } }) },
  { name: 'status-event', expect: 'a delivery receipt, not a patient message: ignored, nothing written',
    body: { object: 'whatsapp_business_account', entry: [{ id: 'TEST_WABA_ID', changes: [{ field: 'messages', value: { messaging_product: 'whatsapp', metadata: { display_phone_number: '15550000000', phone_number_id: DEMO_PHONE_NUMBER_ID }, statuses: [{ id: `wamid.W2TEST.${stamp}.status`, status: 'delivered', timestamp: ts, recipient_id: EXISTING }] } }] }] } },
];

const wrap = (name, expect, body) => ({ json: { __w2_source: 'manual', test_case: name, test_expect: expect, headers: {}, params: {}, query: {}, body } });
if (PASTED_PAYLOAD !== null) return [wrap('pasted-payload', 'whatever your payload should do', PASTED_PAYLOAD)];
return cases.filter((c) => !ONLY || c.name === ONLY).map((c) => wrap(c.name, c.expect, c.body));

// Reads the Meta WhatsApp Cloud API webhook body (entry[].changes[].value) and returns ONE envelope item:
//   kind 'message' = at least one inbound patient message (in events[]) | 'status' = delivery receipts only |
//   'ignored' = Meta-shaped but nothing to store | 'invalid' = not a Meta webhook body at all.
// It never throws. headers / query / params are dropped here so they do not travel through the rest of the workflow.
const raw = $json.body;
const source = $json.__w2_source === 'manual' ? 'manual' : 'webhook';   // only the manual-test node can set this (it is a top-level key, not part of the body)
const cfg = {};
for (const [k, v] of Object.entries($json)) {
  if (['headers', 'params', 'query', 'body', 'webhookUrl', 'executionMode'].includes(k) || k.startsWith('__w2')) continue;
  cfg[k] = v;                                                              // Config values (and test_case / test_expect for the manual test)
}
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const noControl = (v) => String(v === null || v === undefined ? '' : v).replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '');
const line = (v, max) => noControl(v).replace(/\s+/g, ' ').trim().slice(0, max);
const text = (v, max) => noControl(v).trim().slice(0, max);               // keeps line breaks
const nowSec = Math.floor(Date.now() / 1000);
const MAX_EVENTS = 100;

const events = [];
const rejected = [];
let statuses = 0;

const done = (kind, extra) => ({
  json: {
    ...cfg, source, kind, events, rejected, statuses_seen: statuses,
    http_status: kind === 'invalid' ? 400 : 200,
    response_body: JSON.stringify(kind === 'invalid' ? { status: 'invalid', error: extra } : { status: kind === 'message' ? 'received' : kind }),
    reject_reason: kind === 'invalid' ? extra : rejected.join('; '),
  },
});

if (!isObj(raw) || !Array.isArray(raw.entry)) return done('invalid', 'body is not a Meta webhook payload (entry[] is missing)');

for (const entry of raw.entry) {
  if (!isObj(entry) || !Array.isArray(entry.changes)) continue;
  for (const change of entry.changes) {
    const v = isObj(change) ? change.value : null;
    if (!isObj(v)) continue;
    if (Array.isArray(v.statuses)) statuses += v.statuses.length;
    if (!Array.isArray(v.messages) || !v.messages.length) continue;       // delivery receipts, template updates, ...: not patient messages
    const pid = isObj(v.metadata) ? line(v.metadata.phone_number_id, 40) : '';
    const contacts = Array.isArray(v.contacts) ? v.contacts.filter(isObj) : [];
    for (const m of v.messages) {
      if (events.length >= MAX_EVENTS) { rejected.push(`more than ${MAX_EVENTS} messages in one payload: the rest were ignored`); break; }
      if (!isObj(m)) { rejected.push('a message entry is not an object'); continue; }
      const id = line(m.id, 200);
      const from = line(m.from, 30);
      const problems = [];
      if (!pid) problems.push('missing metadata.phone_number_id');
      if (!id) problems.push('missing message id');
      if (!from) problems.push('missing sender phone');
      if (problems.length) { rejected.push(problems.join(', ')); continue; }

      const type = line(m.type, 30).toLowerCase() || 'unknown';
      const part = isObj(m[type]) ? m[type] : {};
      let label = '';                                                       // what the patient actually wrote, when there is text
      if (type === 'text') label = text(part.body, 2000);
      else if (type === 'button') label = text(part.text || part.payload, 2000);
      else if (type === 'interactive' && isObj(m.interactive)) {
        const reply = isObj(m.interactive.button_reply) ? m.interactive.button_reply : (isObj(m.interactive.list_reply) ? m.interactive.list_reply : {});
        label = text(reply.title, 2000);
      }
      const caption = type === 'text' ? '' : text(part.caption, 500);
      const body_text = label || `[WhatsApp ${type} received]${caption ? `: ${caption}` : ''}`;

      const ts = Number(m.timestamp);
      const contact = contacts.find((c) => String(c.wa_id || '') === from) || (contacts.length === 1 ? contacts[0] : null);
      events.push({
        phone_number_id: pid,
        from,
        sender_name: contact && isObj(contact.profile) ? line(contact.profile.name, 100) : '',
        wa_message_id: id,
        msg_timestamp: Number.isFinite(ts) && ts > 0 ? Math.floor(ts) : nowSec,
        msg_type: type,
        body_text,
        enquiry_text: label.slice(0, 1000),
      });
    }
  }
}

if (events.length) return done('message');
if (rejected.length) return done('ignored');
return done(statuses ? 'status' : 'ignored');

// One item per inbound message (Meta may batch several in one webhook). The next node processes them ONE AT A TIME,
// so two messages from the same new patient can never create two leads, and Lead_ids stay unique inside a batch.
const out = [];
$input.all().forEach((item, i) => {
  const { events, rejected, statuses_seen, http_status, response_body, reject_reason, kind, ...ctx } = item.json;
  for (const ev of events || []) out.push({ json: { ...ctx, ...ev }, pairedItem: { item: i } });
});
return out;

// phone_number_id -> clinic. The Agency Registry table Clinics is small, so it is read whole and matched here as TEXT
// (a Grist column holding the id as a number or as text both work). Active may come back as true or the string "TRUE".
const ctx = $('W2 – Loop Over Messages').item.json;
const rows = Array.isArray($json.records) ? $json.records : [];
const want = String(ctx.phone_number_id || '').trim();
const rec = rows.find((r) => r && r.fields && String(r.fields.WA_Phone_Number_ID === undefined || r.fields.WA_Phone_Number_ID === null ? '' : r.fields.WA_Phone_Number_ID).trim() === want);
const f = rec ? rec.fields : {};
const active = !!rec && String(f.Active).toUpperCase() === 'TRUE';
const doc = rec ? String(f.Grist_Doc_ID || '').trim() : '';
let reason = '';
if (!want) reason = 'no phone_number_id';
else if (!rec) reason = 'unknown phone_number_id';
else if (!active) reason = 'clinic is not active';
else if (!doc) reason = 'clinic has no Grist_Doc_ID';
return {
  json: {
    ...ctx,
    clinic_found: reason === '',
    clinic_reject_reason: reason,
    clinic_slug: rec ? String(f.Clinic_Slug || '') : '',
    clinic_name: rec ? String(f.Clinic_Name || '') : '',
    doc_id: reason === '' ? doc : '',
    wa_phone_number_id: want,
  },
};

// Pasted from n8n/snippets/normalize-phone.js (the same function W12 uses) - keep identical.
function normalizeIndianPhone(raw) {
  if (raw === null || raw === undefined) return { phone: null, valid: false };
  let digits = String(raw).replace(/\D/g, '');          // keep digits only
  if (digits.startsWith('0091')) digits = digits.slice(4);
  else if (digits.length === 12 && digits.startsWith('91')) digits = digits.slice(2);
  else if (digits.length === 11 && digits.startsWith('0')) digits = digits.slice(1);
  const valid = /^[6-9]\d{9}$/.test(digits);            // Indian mobiles start 6-9
  return { phone: valid ? `+91${digits}` : null, valid };
}

// WhatsApp gives the sender as digits with the country code (919000000011). Store ONE form only: +91XXXXXXXXXX (CLAUDE.md rule 7).
const { phone, valid } = normalizeIndianPhone($json.from);
return {
  json: {
    ...$json,
    patient_phone: phone,
    phone_valid: valid,
    run_outcome: valid ? '' : 'skipped',
    run_error: valid ? '' : 'sender number is not a valid Indian mobile (+91XXXXXXXXXX); nothing was stored',
  },
};

// Has this WA_Message_ID been stored before? Meta retries deliveries, so the same id can arrive twice.
const ctx = $('W2 – Normalize Phone').item.json;
const rows = Array.isArray($json.records) ? $json.records : [];
const dup = rows.length > 0;
return {
  json: {
    ...ctx,
    is_duplicate: dup,
    run_outcome: dup ? 'skipped' : '',
    run_error: dup ? `duplicate WA_Message_ID (Messages row ${rows[0].id}); nothing was created` : '',
  },
};

const ctx = $('W2 – Read Duplicate').item.json;
const rec = Array.isArray($json.records) ? $json.records[0] : null;
return {
  json: {
    ...ctx,
    lead_found: !!rec,
    lead_row_id: rec ? rec.id : 0,
    lead_id: rec ? String((rec.fields || {}).Lead_id || `row ${rec.id}`) : '',
    lead_created: false,
  },
};

// Same Lead_id rule as W1: L-YYYYMMDD-NNNN (IST date, next free number of the day, read from the 200 newest leads).
const ctx = $('W2 – Read Lead').item.json;
const now = Date.now();
const ymd = new Date(now + 5.5 * 3600 * 1000).toISOString().slice(0, 10).replace(/-/g, '');   // IST date
const prefix = `L-${ymd}-`;
let max = 0;
for (const r of $json.records || []) {
  const id = String((r.fields || {}).Lead_id || '');
  if (id.startsWith(prefix)) max = Math.max(max, parseInt(id.slice(prefix.length), 10) || 0);
}
const lead_id = prefix + String(max + 1).padStart(4, '0');
const fields = {
  Lead_id: lead_id,
  Created_At: Math.floor(now / 1000),                                   // Grist DateTime = epoch seconds
  Name: ctx.sender_name || ctx.default_lead_name || 'WhatsApp Lead',
  Phone: ctx.patient_phone,
  Source: 'WhatsApp',
  Status: 'New',
};
if (ctx.enquiry_text) fields.Enquiry = ctx.enquiry_text;                // only when the patient wrote text
return { json: { ...ctx, new_lead_id: lead_id, create: { records: [{ fields }] } } };

// Race guard. Two messages from the same NEW patient can arrive in parallel (two executions), and both would create a lead.
// After creating, look again: whoever sees several leads for this phone uses the LOWEST row id, so both runs end up on the same lead.
// The extra row is left for staff to delete (W2 never deletes) and is named in the Run_Log note.
const ctx = $('W2 – Build New Lead').item.json;
const made = $('W2 – Create Lead').item.json;
const madeId = made && Array.isArray(made.records) && made.records[0] ? Number(made.records[0].id) : 0;
const rows = (Array.isArray($json.records) ? $json.records : []).filter((r) => r && Number.isInteger(r.id)).sort((a, b) => a.id - b.id);
const canon = rows[0] || (madeId ? { id: madeId, fields: { Lead_id: ctx.new_lead_id } } : null);
const race = !!canon && madeId > 0 && canon.id !== madeId;
const notes = Array.isArray(ctx.race_notes) ? ctx.race_notes.slice() : [];
if (race) notes.push(`parallel messages created lead row ${madeId} as a duplicate of row ${canon.id}; row ${canon.id} is used (row ${madeId} can be deleted)`);
return {
  json: {
    ...ctx,
    lead_found: false,
    lead_row_id: canon ? canon.id : 0,
    lead_id: canon ? String((canon.fields || {}).Lead_id || ctx.new_lead_id) : '',
    lead_created: !!canon && !race,
    race_notes: notes,
    run_outcome: canon ? '' : 'failed',
    run_error: canon ? '' : 'the lead was not found after it was created; message not stored',
  },
};

const ctx = $('W2 – Lead Ready').item.json;
const rows = (Array.isArray($json.records) ? $json.records : []).filter((r) => r && Number.isInteger(r.id)).sort((a, b) => a.id - b.id);
const conv = rows[0] || null;                                           // several rows for one phone: the oldest wins
const f = conv ? conv.fields || {} : {};
return {
  json: {
    ...ctx,
    conversation_found: !!conv,
    conversation_id: conv ? conv.id : 0,
    conversation_created: false,
    conv_unread: Number(f.Unread) || 0,
    conv_last_inbound: Number(f.Last_Inbound_At) || 0,
  },
};

// Same race guard as for leads: after creating, the lowest conversation row id for this phone is the one everybody uses.
const ctx = $('W2 – Read Conversation').item.json;
const made = $('W2 – Create Conversation').item.json;
const madeId = made && Array.isArray(made.records) && made.records[0] ? Number(made.records[0].id) : 0;
const rows = (Array.isArray($json.records) ? $json.records : []).filter((r) => r && Number.isInteger(r.id)).sort((a, b) => a.id - b.id);
const conv = rows[0] || (madeId ? { id: madeId, fields: {} } : null);
const f = conv ? conv.fields || {} : {};
const race = !!conv && madeId > 0 && conv.id !== madeId;
const notes = Array.isArray(ctx.race_notes) ? ctx.race_notes.slice() : [];
if (race) notes.push(`parallel messages created conversation row ${madeId} as a duplicate of row ${conv.id}; row ${conv.id} is used (row ${madeId} can be deleted)`);
return {
  json: {
    ...ctx,
    conversation_found: false,
    conversation_id: conv ? conv.id : 0,
    conversation_created: !!conv && !race,
    conv_unread: Number(f.Unread) || 0,
    conv_last_inbound: Number(f.Last_Inbound_At) || 0,
    race_notes: notes,
    run_outcome: conv ? '' : 'failed',
    run_error: conv ? '' : 'the conversation was not found after it was created; message not stored',
  },
};

// The Messages row exists. Work out the conversation update: Last_Inbound_At never moves backwards (messages can arrive out of order),
// Unread counts up by one (grist/schema.md: Integer) - or becomes true when unread_mode is 'flag' (a Toggle column).
// This runs only for a NEW WA_Message_ID (duplicates stop earlier), so Unread can never be counted twice for one message.
const ctx = $('W2 – Conversation Ready').item.json;
const rec = Array.isArray($json.records) ? $json.records[0] : null;
const unread = ctx.unread_mode === 'flag' ? true : (Number(ctx.conv_unread) || 0) + 1;
const lastInbound = Math.max(Number(ctx.conv_last_inbound) || 0, ctx.msg_timestamp);
return {
  json: {
    ...ctx,
    message_row_id: rec ? Number(rec.id) || 0 : 0,
    conv_update: { records: [{ id: ctx.conversation_id, fields: { Lead: ctx.lead_row_id, Last_Inbound_At: lastInbound, Unread: unread } }] },
  },
};

// Staff alert for a brand-new lead: the PAYLOAD only. W2 sends nothing and does not call W12 (the one WhatsApp sender).
// decision.send is false on purpose, so even if this item is wired to W12 by mistake nothing is sent. After the merge, a guard node
// must fill decision (owner phone from Settings, TEST_MODE / TEST_PHONE, quiet hours) exactly like W3 does, then call W12.
const ctx = $('W2 – Message Saved').item.json;
const saved = ctx.message_row_id > 0;
let staff_alert = null;
if (ctx.lead_created === true) {
  const name = ctx.sender_name || ctx.default_lead_name || 'WhatsApp Lead';
  const quote = ctx.enquiry_text ? ` - "${ctx.enquiry_text.replace(/\s+/g, ' ').slice(0, 200)}"` : '';
  staff_alert = {
    prepared: true,
    audience: 'staff',
    source_workflow: 'W2-WhatsApp-Inbound',
    template: 'new_lead_staff_alert',                                  // W12's WA_TEMPLATES: clinic_name, lead_name, lead_phone, enquiry
    template_params: { clinic_name: ctx.clinic_name, lead_name: name, lead_phone: ctx.patient_phone, enquiry: ctx.enquiry_text || '' },
    message_text: `New WhatsApp lead (${ctx.clinic_name}): ${name}, ${ctx.patient_phone}${quote}. ${ctx.lead_id}.`,
    wa_phone_number_id: ctx.wa_phone_number_id,
    grist_base_url: ctx.grist_base_url,
    doc_id: ctx.doc_id,
    lead_row_id: ctx.lead_row_id,
    lead_phone: ctx.patient_phone,
    decision: { send: false, to: null, reason: 'W2 standalone: staff alert prepared only, not sent', test_mode: true },
  };
}
return {
  json: {
    ...ctx,
    staff_alert,
    run_outcome: saved ? 'ok' : 'failed',
    run_error: saved ? '' : 'the message insert returned no row id',
  },
};

// The one place that turns any outcome (stored, skipped, failed) into a Run_Log row.
// Input is either (a) a full item with run_outcome / run_error, or (b) the error output of a Grist HTTP node ({ error }), in which case the
// message's context is taken from the nearest earlier stage of THIS message. No phone numbers are written: numbers are masked.
const STAGES = ['W2 – Message Saved', 'W2 – Conversation Ready', 'W2 – Read Created Conversation', 'W2 – Read Conversation', 'W2 – Lead Ready',
  'W2 – Read Created Lead', 'W2 – Read Lead', 'W2 – Read Duplicate', 'W2 – Normalize Phone', 'W2 – Resolve Clinic'];
const from = (name) => { try { return $(name).item.json; } catch (e) { return null; } };   // throws when that stage did not run for this message
const isFull = $json && $json.wa_message_id !== undefined;
const loop = from('W2 – Loop Over Messages');
let ctx = null;
let stage = '';
if (isFull) ctx = $json;
else {
  for (const s of STAGES) {
    const c = from(s);
    if (c && (!loop || c.wa_message_id === loop.wa_message_id)) { ctx = c; stage = s.replace('W2 – ', ''); break; }   // same message id = not left over from an earlier loop round
  }
  if (!ctx) ctx = loop || {};
}

const safe = (v, max) => String(v === undefined || v === null ? '' : v).replace(/bearer\s+\S+/gi, 'bearer [hidden]').replace(/\s+/g, ' ').trim().slice(0, max);
const failedHttp = !isFull;
const outcome = failedHttp ? 'failed' : (ctx.run_outcome || 'ok');
let err;
if (failedHttp) {
  const e = $json && $json.error;
  const msg = safe(e && typeof e === 'object' ? (e.message || e.description || JSON.stringify(e)) : e, 300) || 'unknown error';
  err = `Grist request failed${stage ? ` after "${stage}"` : ''}: ${msg}`;
} else if (outcome === 'ok' && Array.isArray(ctx.race_notes) && ctx.race_notes.length) err = ctx.race_notes.join('; ');
else err = ctx.run_error || '';

const mask = (p) => String(p || '').replace(/\d(?=\d{4})/g, '*');
const id = ctx.wa_message_id || '';
const record = !failedHttp && outcome === 'ok'
  ? `${ctx.lead_id || 'lead'} ${id} (${ctx.lead_created ? 'new lead' : 'existing lead'}, ${ctx.msg_type || 'message'})`
  : `${id} ${mask(ctx.patient_phone || ctx.from)}`.trim();

return {
  json: {
    can_log: !!(ctx.grist_base_url && ctx.doc_id),                      // no clinic resolved = no CRM to log into
    grist_base_url: ctx.grist_base_url,
    doc_id: ctx.doc_id,
    log: { Workflow: 'W2-WhatsApp-Inbound', Record: safe(record, 200), Outcome: outcome, Error: safe(err, 500), At: Math.floor(Date.now() / 1000) },
    outcome,
    wa_message_id: id,
    lead_row_id: ctx.lead_row_id || 0,
    conversation_id: ctx.conversation_id || 0,
    message_row_id: ctx.message_row_id || 0,
    staff_alert: ctx.staff_alert || null,
    test_case: ctx.test_case,
  },
};

// ONE job for the AI receptionist (SECTION W13) per stored patient message. Only identifiers: W13 reads the message text, the
// lead, the conversation and the clinic from Grist itself (the stored row is the source of truth) and its settings from
// W13 – Config. w13_job routes the call at "W12 – AI Job?". text is passed for the record; W13 uses the stored Body.
return {
  json: {
    w13_job: true,
    dry_run: false,
    w13_retry: false,
    wa_phone_number_id: $json.wa_phone_number_id,
    clinic_slug: $json.clinic_slug,
    message_row_id: $json.message_row_id,
    wa_message_id: $json.wa_message_id,
    msg_type: $json.msg_type,
    patient_phone: $json.patient_phone,
    sender_name: $json.sender_name,
    text: $json.body_text,
  },
};

// The AI receptionist runs as its own execution (W2 does not wait: Meta already has its 200 and the next message goes on).
// W2 continues with ITS item for this message, so Build Run Log / Run Log work exactly as before. If the AI job could not
// even be started, the message is still stored: Run_Log stays ok and its Error column says so (race_notes, as W2 already does).
const ctx = $('W2 – Prepare Staff Alert').item.json;
const e = $json && $json.error;
if (!e) return { json: ctx };
const why = String(e.message || e.description || e).replace(/\s+/g, ' ').slice(0, 200);
return { json: { ...ctx, race_notes: [...(Array.isArray(ctx.race_notes) ? ctx.race_notes : []), `AI receptionist not started: ${why}`] } };

// 08:05 IST: every active clinic with a Grist doc and a WhatsApp number (messages deferred overnight are answered now).
const cfg = $('W13 – Config').first().json;
const txt = (v) => String(v === undefined || v === null ? '' : v).trim();
return ($json.records || [])
  .filter((r) => r && r.fields && txt(r.fields.Active).toUpperCase() === 'TRUE' && txt(r.fields.Grist_Doc_ID) && txt(r.fields.WA_Phone_Number_ID))
  .map((r) => ({ json: { grist_base_url: cfg.grist_base_url, doc_id: txt(r.fields.Grist_Doc_ID), wa_phone_number_id: txt(r.fields.WA_Phone_Number_ID), clinic_slug: txt(r.fields.Clinic_Slug) } }));

// Deferred messages (they came in at night) to answer now: per conversation only the NEWEST one (it sees the others in its
// history), and only from the last 20 hours (inside WhatsApp's 24-hour reply window). Each goes through the normal W13 run.
const clinics = $('W13 – Active Clinics').all();
const nowSec = Math.floor(Date.now() / 1000);
const out = [];
$input.all().forEach((it, i) => {
  const c = clinics[i] && clinics[i].json;
  if (!c || it.json.error) return;                     // that clinic's Messages could not be read: try again tomorrow
  const newest = {};
  for (const r of it.json.records || []) {
    const f = r.fields || {};
    if (f.Direction === 'Out' || !(Number(f.Created_At) >= nowSec - 20 * 3600)) continue;
    const k = String(f.Conversation || `row-${r.id}`);
    if (!newest[k] || f.Created_At > newest[k].fields.Created_At || (f.Created_At === newest[k].fields.Created_At && r.id > newest[k].id)) newest[k] = r;
  }
  for (const r of Object.values(newest)) {
    out.push({ json: { wa_phone_number_id: c.wa_phone_number_id, message_row_id: r.id, wa_message_id: String(r.fields.WA_Message_ID || ''), w13_retry: true } });
  }
});
return out.slice(0, 200);

// Pasted from n8n/snippets/normalize-phone.js - keep identical.
function normalizeIndianPhone(raw) {
  if (raw === null || raw === undefined) return { phone: null, valid: false };
  let digits = String(raw).replace(/\D/g, '');          // keep digits only
  if (digits.startsWith('0091')) digits = digits.slice(4);
  else if (digits.length === 12 && digits.startsWith('91')) digits = digits.slice(2);
  else if (digits.length === 11 && digits.startsWith('0')) digits = digits.slice(1);
  const valid = /^[6-9]\d{9}$/.test(digits);            // Indian mobiles start 6-9
  return { phone: valid ? `+91${digits}` : null, valid };
}

// W13 handles ONE patient message per run: W2 calls it once per message ("Run once for each item"), the manual test and the
// morning retry call it the same way. This node checks that, and keeps only the fields W13 uses.
const items = $input.all();
if (items.length !== 1) throw new Error(`W13 handles one message per run but got ${items.length} items: call it with mode "Run once for each item"`);
const j = items[0].json;
const dry = j.dry_run === true;
return [{
  json: {
    // W13 – Config
    grist_base_url: j.grist_base_url,
    registry_doc_id: j.registry_doc_id,
    leads_table: j.leads_table,
    anthropic_model: j.anthropic_model,
    openrouter_model: j.openrouter_model,
    w12_workflow_id: String(j.w12_workflow_id || '').trim(),
    min_confidence: Number(j.min_confidence),
    confidence_auto: Number(j.confidence_auto),
    confidence_write: Number(j.confidence_write),
    max_ai_replies_per_hour: Number(j.max_ai_replies_per_hour),
    history_limit: Number(j.history_limit),
    slot_days: Number(j.slot_days),
    pause_on_handoff: j.pause_on_handoff === true,
    staff_alert_template: j.staff_alert_template,
    // the message (from W2, the morning retry or a test)
    dry_run: dry,
    w13_retry: j.w13_retry === true,
    wa_phone_number_id: String(j.wa_phone_number_id || '').trim(),
    clinic_slug: String(j.clinic_slug || '').trim(),
    message_row_id: Number(j.message_row_id) || 0,
    wa_message_id: String(j.wa_message_id || '').trim(),
    msg_type: j.msg_type ? String(j.msg_type) : '',
    patient_phone: normalizeIndianPhone(j.patient_phone).phone || '',
    sender_name: String(j.sender_name || '').slice(0, 60),
    text: dry ? String(j.text || '') : '',              // a real run reads the text from the Messages row, never from the caller
    test_case: String(j.test_case || ''),
  },
}];

// The clinic, from the Agency Registry (CLAUDE.md "Clinic lookup"): by WhatsApp phone_number_id (W2, retries), or by
// Clinic_Slug (tests). Active must be TRUE and the clinic must have a Grist doc. Nothing is hard-coded.
const st = $('W13 – Start').first().json;
const rows = Array.isArray($json.records) ? $json.records : [];
const txt = (v) => String(v === undefined || v === null ? '' : v).trim();
const rec = st.wa_phone_number_id
  ? rows.find((r) => r && r.fields && txt(r.fields.WA_Phone_Number_ID) === st.wa_phone_number_id)
  : rows.find((r) => r && r.fields && st.clinic_slug && txt(r.fields.Clinic_Slug) === st.clinic_slug);
const f = rec ? rec.fields : {};
let reason = '';
if ($json.error) reason = `Agency Registry not readable: ${txt($json.error.message || $json.error).slice(0, 200)}`;
else if (!st.wa_phone_number_id && !st.clinic_slug) reason = 'no wa_phone_number_id or clinic_slug in the input';
else if (!rec) reason = 'clinic not found in the Agency Registry';
else if (txt(f.Active).toUpperCase() !== 'TRUE') reason = 'clinic is not active';
else if (!txt(f.Grist_Doc_ID)) reason = 'clinic has no Grist_Doc_ID';
return [{
  json: {
    clinic_ok: reason === '',
    reason,
    grist_base_url: st.grist_base_url,
    doc_id: reason ? '' : txt(f.Grist_Doc_ID),
    clinic_name: txt(f.Clinic_Name),
    clinic_slug: txt(f.Clinic_Slug),
    wa_phone_number_id: txt(f.WA_Phone_Number_ID),
  },
}];

// Unknown or inactive clinic: there is no CRM to write to, so W13 stops here (W2 already stored the message).
const c = $json;
return [{ json: { status: 'skipped', reason: c.reason, test_case: $('W13 – Start').first().json.test_case } }];

// Which conversation: the one the message row points at; a dry run (no row) looks it up by the patient's phone.
const st = $('W13 – Start').first().json;
const msg = (Array.isArray($json.records) ? $json.records : [])[0];
const conv = msg && msg.fields && Number(msg.fields.Conversation) > 0 ? Number(msg.fields.Conversation) : 0;
return [{ json: { conversation_filter: conv ? { id: [conv] } : { Phone: [st.patient_phone || '-'] } } }];

// Which lead: the one the conversation points at, else the lead with the patient's phone (W2 makes one lead per phone; the
// lowest row id wins if there are more). Also the conversation row id for the history read.
const st = $('W13 – Start').first().json;
const convs = (Array.isArray($json.records) ? $json.records : []).filter((r) => r && r.fields).sort((a, b) => a.id - b.id);
const conv = convs[0];
const leadId = conv && Number(conv.fields.Lead) > 0 ? Number(conv.fields.Lead) : 0;
const phone = (conv && conv.fields.Phone) || st.patient_phone || '-';
return [{ json: { lead_filter: leadId ? { id: [leadId] } : { Phone: [phone] }, conversation_id: conv ? conv.id : 0 } }];

// ---- pasted from n8n/snippets/ (normalize-phone.js, send-guard.js, clinic-hours.js, ai-receptionist.js) - keep identical ----
function normalizeIndianPhone(raw) {
  if (raw === null || raw === undefined) return { phone: null, valid: false };
  let digits = String(raw).replace(/\D/g, '');          // keep digits only
  if (digits.startsWith('0091')) digits = digits.slice(4);
  else if (digits.length === 12 && digits.startsWith('91')) digits = digits.slice(2);
  else if (digits.length === 11 && digits.startsWith('0')) digits = digits.slice(1);
  const valid = /^[6-9]\d{9}$/.test(digits);            // Indian mobiles start 6-9
  return { phone: valid ? `+91${digits}` : null, valid };
}

function isTestMode(value) {
  const v = String(value === null || value === undefined ? '' : value).trim().toLowerCase();
  return !['false', '0', 'no', 'off'].includes(v);   // anything else, including a missing row, means ON (fail safe)
}

function inQuietHours(nowMs) {
  if (!Number.isFinite(nowMs)) return true;           // no clock, no send
  const hourIST = new Date(nowMs + 5.5 * 3600 * 1000).getUTCHours();
  return hourIST >= 21 || hourIST < 8;
}

function decideSend(i) {
  const testMode = isTestMode(i.test_mode);
  const skip = (reason) => ({ send: false, to: null, reason, test_mode: testMode });

  if (i.flag_value) return skip('already sent');
  if (i.opted_out) return skip('opted out');
  if (i.kind !== 'transactional' && i.automation_paused) return skip('automation paused');
  if (inQuietHours(i.now_ms)) return skip('quiet hours');

  const to = testMode ? i.test_phone : i.patient_phone;
  if (!to) return skip(testMode ? 'test mode on but TEST_PHONE is missing or invalid' : 'no valid patient phone');
  return { send: true, to, reason: testMode ? 'test mode: sent to TEST_PHONE' : 'ok', test_mode: testMode };
}

const DAY_INDEX = { sun: 0, mon: 1, tue: 2, wed: 3, thu: 4, fri: 5, sat: 6 };

function parseClock(text) {
  const m = String(text === null || text === undefined ? '' : text).trim().match(/^(\d{1,2})(?:[:.](\d{2}))?\s*(a\.?m\.?|p\.?m\.?)?$/i);
  if (!m) return null;
  let h = parseInt(m[1], 10);
  const min = m[2] ? parseInt(m[2], 10) : 0;
  const meridiem = m[3] ? m[3][0].toLowerCase() : '';
  if (min > 59) return null;
  if (meridiem) {
    if (h < 1 || h > 12) return null;
    h = (h % 12) + (meridiem === 'p' ? 12 : 0);
  } else if (h > 24 || (h === 24 && min > 0)) {
    return null;
  }
  return h * 60 + min;   // minutes after midnight
}

function parseDays(text) {
  const s = String(text === null || text === undefined ? '' : text).toLowerCase().replace(/[–—]/g, '-').replace(/\s+to\s+/g, '-').replace(/\s+(and|&)\s+/g, ',').trim();
  if (!s) return null;
  if (/^(daily|every ?day|all days|7 ?days?)$/.test(s)) return [0, 1, 2, 3, 4, 5, 6];
  const dayOf = (t) => {
    const x = t.trim();
    return /^(sun|mon|tue|wed|thu|fri|sat)[a-z]*\.?$/.test(x) ? DAY_INDEX[x.slice(0, 3)] : undefined;
  };
  const days = new Set();
  for (const token of s.split(/[,;/]+/)) {
    if (!token.trim()) continue;
    if (token.includes('-')) {
      const [a, b] = token.split('-').map(dayOf);
      if (a === undefined || b === undefined) return null;
      for (let d = a; ; d = (d + 1) % 7) { days.add(d); if (d === b) break; }
    } else {
      const d = dayOf(token);
      if (d === undefined) return null;
      days.add(d);
    }
  }
  return days.size ? [...days].sort() : null;   // 0 = Sunday
}

const AI_INTENTS = ['greeting', 'services_info', 'pricing', 'location_hours', 'availability_check', 'book_appointment',
  'reschedule_appointment', 'cancel_appointment', 'appointment_status', 'follow_up_later', 'not_interested', 'thanks_ack',
  'complaint', 'human_request', 'payment_issue', 'medical_question', 'outcome_better', 'outcome_same', 'outcome_worse', 'other'];
const AI_ACTIONS = ['reply', 'offer_slots', 'book_slot', 'cancel_appointment', 'reschedule_appointment', 'schedule_follow_up', 'handoff', 'no_reply'];
const AI_HUMAN_INTENTS = ['complaint', 'human_request', 'payment_issue', 'medical_question', 'outcome_same', 'outcome_worse'];   // always a human, whatever the model says
// How a hand-off reason names these intents (the rest: the intent with spaces). Outcome = the patient's answer to W7's check-in.
const AI_INTENT_LABELS = { outcome_same: 'no improvement after the visit', outcome_worse: 'feels worse after the visit' };
// A staff member wrote to the patient (a Messages row Direction Out that no automation wrote, e.g. a W10 reply) less than this
// before the patient's message: the conversation is theirs and the AI stays out (it comes back this long after their last message).
const AI_STAFF_WINDOW_SEC = 24 * 3600;
const AI_STAGES = ['cold', 'warm', 'hot'];
const AI_SENTIMENTS = ['positive', 'neutral', 'negative'];
const AI_WINDOWS = { morning: [8 * 60, 12 * 60], afternoon: [12 * 60, 16 * 60], evening: [16 * 60, 21 * 60] };
const AI_PLACEHOLDERS = ['{{BOOKING_LINK}}', '{{CANCEL_LINK}}', '{{RESCHEDULE_LINK}}'];
const AI_STOP_WORDS = /^\s*(stop|unsubscribe|stop all|stop messages?|opt[ -]?out|band karo|mat bhejo|messages band karo)\s*[.!]*\s*$/i;
const AI_IST = 5.5 * 3600 * 1000;
const AI_DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];
const AI_DAY_WORDS = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];
const AI_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const AI_WORKFLOW = 'W13-ai-receptionist';
// Triage (A3): how urgent a hand-off is, and why. Any risk flag or priority "urgent" always means a person answers.
const AI_PRIORITIES = ['urgent', 'high', 'normal'];
const AI_RISK_FLAGS = ['emergency', 'complaint', 'payment', 'medical', 'legal', 'abusive', 'sensitive'];
// Confidence tiers (A4): between min_confidence and confidence_auto only these informational answers may go out on their own.
const AI_INFO_INTENTS = ['greeting', 'services_info', 'pricing', 'location_hours', 'availability_check', 'appointment_status', 'thanks_ack', 'outcome_better'];
const AI_INFO_ACTIONS = ['reply', 'offer_slots', 'no_reply'];
const AI_NO_REPLY_INTENTS = ['thanks_ack', 'not_interested', 'outcome_better'];   // no_reply for anything else = a person answers (live rule, A1)
// Deterministic emergency check (A3), before any AI. Only unambiguous phrases: stroke, paralysis, fracture or accident are
// everyday physio rehab topics and would raise false URGENT alerts (the model can still flag them as risks).
const AI_EMERGENCY = /\b(chest pain|heart attack|can'?t breathe|cannot breathe|unable to breathe|difficulty (in )?breathing|not breathing|unconscious|fainted|passed out|collapsed|heavy bleeding|bleeding heavily|severe bleeding|bleeding a lot|suicid\w*|kill myself|end my life|self[- ]harm|medical emergency|(it'?s|this is) an emergency|emergency hai|seene me(in)? dard|chhati me(in)? dard|saans (nahi|nahin|lene me(in)?)|behosh|aatmahatya)\b|सीने में दर्द|छाती में दर्द|सांस नहीं|साँस नहीं|बेहोश|आत्महत्या/i;

const aiNullable = (schema) => ({ anyOf: [schema, { type: 'null' }] });
const AI_DECISION_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['intent', 'action', 'needs_human', 'handoff_reason', 'confidence', 'sentiment', 'language', 'lead_stage', 'reply',
    'booking', 'appointment_ref', 'follow_up_days', 'kb_refs', 'likely_service', 'lead_summary', 'priority', 'staff_note', 'risk_flags'],
  properties: {
    intent: { type: 'string', enum: AI_INTENTS },
    action: { type: 'string', enum: AI_ACTIONS },
    needs_human: { type: 'boolean' },
    handoff_reason: { type: 'string' },
    confidence: { type: 'number' },
    sentiment: { type: 'string', enum: AI_SENTIMENTS },
    language: { type: 'string' },
    lead_stage: { type: 'string', enum: AI_STAGES },
    reply: { type: 'string' },
    booking: {
      type: 'object',
      additionalProperties: false,
      required: ['date', 'time', 'time_window'],
      properties: {
        date: aiNullable({ type: 'string' }),
        time: aiNullable({ type: 'string' }),
        time_window: aiNullable({ type: 'string', enum: Object.keys(AI_WINDOWS) }),
      },
    },
    appointment_ref: aiNullable({ type: 'string' }),
    follow_up_days: aiNullable({ type: 'integer' }),
    kb_refs: { type: 'array', items: { type: 'string' } },
    likely_service: aiNullable({ type: 'string' }),
    lead_summary: { type: 'string' },
    priority: { type: 'string', enum: AI_PRIORITIES },
    staff_note: { type: 'string' },
    risk_flags: { type: 'array', items: { type: 'string', enum: AI_RISK_FLAGS } },
  },
};

// ---------------------------------------------------------------- small helpers
function aiClean(v, max) {
  return String(v === null || v === undefined ? '' : v).replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '').trim().slice(0, max);
}
function aiLine(v, max) { return aiClean(v, 10000).replace(/\s+/g, ' ').slice(0, max); }
function aiIst(ms) {
  const t = new Date(ms + AI_IST);
  return { date: t.toISOString().slice(0, 10), minutes: t.getUTCHours() * 60 + t.getUTCMinutes(), weekday: t.getUTCDay() };
}
function aiIstMs(date, minutes) { return Date.parse(`${date}T00:00:00+05:30`) + minutes * 60000; }
function aiDayLabel(date) {
  const t = new Date(Date.parse(`${date}T00:00:00Z`));
  return `${AI_DAYS[t.getUTCDay()]} ${String(t.getUTCDate()).padStart(2, '0')} ${AI_MONTHS[t.getUTCMonth()]}`;
}
function aiHHMM(m) { return `${String(Math.floor(m / 60)).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}`; }
function ai12h(m) { const hh = Math.floor(m / 60); return `${hh % 12 || 12}:${String(m % 60).padStart(2, '0')} ${hh >= 12 ? 'PM' : 'AM'}`; }
function aiNum(v, dflt) { const n = Number(v); return v !== undefined && v !== null && String(v).trim() !== '' && Number.isFinite(n) && n > 0 && n <= 1 ? n : dflt; }
// A short note for staff: no links or phone numbers (they never come from the AI into a WhatsApp alert), max 200 characters.
function aiStaffNote(v) { return aiLine(String(v === null || v === undefined ? '' : v).replace(/https?:\/\/\S+/gi, '[link]').replace(/\+?\d[\d\s-]{7,}\d/g, '[number]'), 200); }
function aiEmergencyIn(text) { const m = String(text || '').match(AI_EMERGENCY); return m ? aiLine(m[0], 40) : ''; }
function aiTriage(d) {
  const flags = [...new Set((Array.isArray(d && d.risk_flags) ? d.risk_flags : []).filter((f) => AI_RISK_FLAGS.includes(f)))];
  return { priority: d && AI_PRIORITIES.includes(d.priority) ? d.priority : 'normal', flags, note: aiStaffNote(d && d.staff_note) };
}
function aiErrText(r) {
  const e = r && r.error;
  if (!e) return 'no answer';
  return aiLine(typeof e === 'string' ? e : e.message || e.description || JSON.stringify(e), 200);
}

// ---------------------------------------------------------------- reading Grist
function aiSettings(records) {
  const s = {};
  for (const r of records || []) { const f = (r && r.fields) || {}; if (f.Key) s[String(f.Key).trim()] = f.Value; }
  return s;
}

// The clinic's own switches live in Settings (Key / Value). AI is OFF unless the clinic sets ai_mode = draft (AI decides and
// writes the CRM, staff send the reply) or auto (the reply is sent through W12).
function aiProfile(s, registryName) {
  const num = (v, dflt, lo, hi) => { const n = Number(v); return v !== undefined && v !== null && String(v).trim() !== '' && Number.isFinite(n) && n >= lo && n <= hi ? Math.round(n) : dflt; };
  const mode = String(s.ai_mode || '').trim().toLowerCase();
  return {
    clinic_name: aiLine(s.clinic_name || registryName || '', 100),
    ai_mode: ['draft', 'auto'].includes(mode) ? mode : 'off',
    booking_mode: String(s.booking_mode || '').trim().toLowerCase() === 'direct' ? 'direct' : 'link',
    booking_link: /^https:\/\/\S+$/.test(aiLine(s.booking_link, 300)) ? aiLine(s.booking_link, 300) : '',
    slot_minutes: num(s.slot_minutes, 30, 10, 240),
    capacity: num(s.booking_capacity, 1, 1, 20),
    notice_minutes: num(s.booking_notice_minutes, 120, 0, 10080),
    open_time: s.open_time,
    close_time: s.close_time,
    open_hours: s.open_hours,
    working_days: s.working_days,
    handoff_reply: aiClean(s.handoff_reply, 500) || 'Thank you for your message. A member of our team will reply to you shortly.',
    owner_phone: s.owner_phone,
    test_mode: s.TEST_MODE,
    test_phone: s.TEST_PHONE,
  };
}

// Knowledge base rows the AI may use: Title, Category, Content, Active (missing Active = active).
// At most 80 rows and about 24,000 characters go to the AI (a clinic's FAQ is far smaller).
function aiKnowledge(records) {
  let total = 0;
  return (records || [])
    .filter((r) => r && Number.isInteger(r.id) && r.fields && r.fields.Active !== false && String(r.fields.Active).toUpperCase() !== 'FALSE' && aiClean(r.fields.Content, 10))
    .sort((a, b) => a.id - b.id)
    .map((r) => ({ ref: `K${r.id}`, title: aiLine(r.fields.Title, 120), category: aiLine(r.fields.Category || 'general', 40).toLowerCase(), content: aiClean(r.fields.Content, 1500) }))
    .filter((k) => { total += k.title.length + k.content.length; return total <= 24000; })
    .slice(0, 80);
}

function aiCalendar(nowMs, days) {
  const out = [];
  for (let i = 0; i < days; i++) {
    const date = aiIst(nowMs + i * 86400000).date;
    out.push({ date, label: aiDayLabel(date), weekday: AI_DAY_WORDS[new Date(Date.parse(`${date}T00:00:00Z`)).getUTCDay()], relative: i === 0 ? 'today' : i === 1 ? 'tomorrow' : '' });
  }
  return out;
}

// Opening windows of a working day, in minutes after midnight. Settings key open_hours (optional) lists them, e.g. "09:00-13:00, 16:00-20:00"
// (12-hour times also read: "9 AM-1 PM and 4 PM-8 PM"). Without open_hours the single open_time-close_time window is used, exactly as before.
// aiParseWindows: undefined = not set, null = set but unreadable (overlapping, backwards, more than 4, not clocks), else [[open, close], ...] sorted.
function aiParseWindows(text, parseClock) {
  const s = String(text === null || text === undefined ? '' : text).replace(/[–—]/g, '-').trim();
  if (!s) return undefined;
  const out = [];
  for (const part of s.split(/\s*(?:[,;]|\band\b)\s*/i)) {
    if (!part.trim()) continue;
    const ends = part.replace(/\s+to\s+/i, '-').split('-');
    if (ends.length !== 2) return null;
    const open = parseClock(ends[0]);
    const close = parseClock(ends[1]);
    if (open === null || close === null || close <= open) return null;
    out.push([open, close]);
  }
  if (!out.length || out.length > 4) return null;
  out.sort((x, y) => x[0] - y[0]);
  for (let i = 1; i < out.length; i++) if (out[i][0] < out[i - 1][1]) return null;
  return out;
}
// The windows to use, or null when the hours are not known (then no time is ever offered or booked).
function aiHoursWindows(p, h) {
  const w = aiParseWindows(p.open_hours, h.parseClock);
  if (w === null) return null;                    // open_hours is set but unreadable: do not guess, and do not fall back to a wider window
  if (w) return w;
  const open = h.parseClock(p.open_time);
  const close = h.parseClock(p.close_time);
  return open === null || close === null || close <= open ? null : [[open, close]];
}

// Free appointment start times from the clinic's hours and the Booked rows in Appointments (which W4 keeps in step with Cal.com).
// Every slot must start and END inside one opening window (nothing in a lunch break, nothing running past closing, nothing on a non-working day).
// No hours in Settings = no slots at all: the AI must not invent availability.
function aiFreeSlots(p, appointmentRecords, nowMs, days, h) {
  const windows = aiHoursWindows(p, h);
  const working = h.parseDays(p.working_days);
  if (!windows || !working) return { known: false, days: [], slot_minutes: p.slot_minutes };
  const busy = [];
  for (const r of appointmentRecords || []) {
    const f = (r && r.fields) || {};
    if (f.Status !== 'Booked' || typeof f.Start !== 'number') continue;
    const s = f.Start * 1000;
    const e = typeof f.End === 'number' && f.End > f.Start ? f.End * 1000 : s + p.slot_minutes * 60000;
    busy.push([s, e]);
  }
  const earliest = nowMs + p.notice_minutes * 60000;
  const out = [];
  for (const day of aiCalendar(nowMs, days)) {
    if (!working.includes(new Date(Date.parse(`${day.date}T00:00:00Z`)).getUTCDay())) continue;
    const times = [];
    for (const [open, close] of windows) {
      for (let m = open; m + p.slot_minutes <= close; m += p.slot_minutes) {
        const s = aiIstMs(day.date, m);
        const e = s + p.slot_minutes * 60000;
        if (s < earliest) continue;
        if (busy.filter(([bs, be]) => bs < e && be > s).length < p.capacity) times.push(m);
      }
    }
    if (times.length) out.push({ date: day.date, label: day.label, times });
  }
  return { known: true, days: out, slot_minutes: p.slot_minutes, open: windows[0][0], close: windows[windows.length - 1][1], windows };
}

// This patient's upcoming Booked appointments, with short refs (A1, A2...) the AI can point at.
function aiLeadAppointments(appointmentRecords, leadRowId, nowMs) {
  if (!leadRowId) return [];
  return (appointmentRecords || [])
    .filter((r) => r && r.fields && r.fields.Status === 'Booked' && Number(r.fields.Lead) === Number(leadRowId) && typeof r.fields.Start === 'number' && r.fields.Start * 1000 >= nowMs - 3600000)
    .sort((a, b) => a.fields.Start - b.fields.Start)
    .slice(0, 5)
    .map((r, i) => {
      const f = r.fields;
      const t = aiIst(f.Start * 1000);
      const uid = aiLine(f.Booking_UID || `row-${r.id}`, 120);
      return {
        ref: `A${i + 1}`, row_id: r.id, uid, origin: /^wa-/.test(uid) ? 'whatsapp' : 'calcom',
        start: f.Start, end: typeof f.End === 'number' ? f.End : f.Start + 1800, date: t.date, minutes: t.minutes,
        label: `${aiDayLabel(t.date)} ${ai12h(t.minutes)}`, service: aiLine(f.Service, 80), physio: aiLine(f.Physio, 80),
      };
    });
}

// Recent conversation, oldest first, without the message being answered. Direction "Out" = the clinic; anything else = patient.
function aiHistory(records, currentRowId, limit) {
  return (records || [])
    .filter((r) => r && r.fields && r.id !== currentRowId)
    .map((r) => ({ id: r.id, dir: r.fields.Direction === 'Out' ? 'clinic' : 'patient', text: aiLine(r.fields.Body, 300), at: Number(r.fields.Created_At) || 0, by: aiLine(r.fields.Sent_By, 80) }))
    .sort((a, b) => a.at - b.at || a.id - b.id)
    .slice(-limit);
}

// ---------------------------------------------------------------- everything W13 knows about this message
// raw: { start, clinic, settings, knowledge, message, conversation, lead, history, appointments }: each read is Grist's answer
// ({ records }) or n8n's error item ({ error }). start = the caller's item; clinic = the Agency Registry row (doc_id, name, ...).
// cfg: W13 Config. Returns { x, gate }: x is the context every later step uses, gate says whether to ask the AI at all.
function aiContext(raw, cfg, nowMs, h) {
  const recs = (r) => (r && Array.isArray(r.records) ? r.records : null);
  const lowest = (rows) => (rows || []).filter((r) => r && r.fields).sort((a, b) => a.id - b.id)[0] || null;
  const st = raw.start || {};
  const dry = st.dry_run === true;
  const notes = [];
  let failed = '';
  const fail = (why) => { if (!failed) failed = why; };

  const settingsRecs = recs(raw.settings);
  if (!settingsRecs) fail(`could not read Settings: ${aiErrText(raw.settings)}`);
  const profile = aiProfile(aiSettings(settingsRecs), raw.clinic.clinic_name);
  const kbRecs = recs(raw.knowledge);
  if (!kbRecs) notes.push(`Knowledge table not read (${aiErrText(raw.knowledge)}): the AI knows no services or prices`);
  const kb = aiKnowledge(kbRecs);

  // the message being answered (a dry run has no row: its text comes with the test item)
  let msg = null;
  if (!dry) {
    const m = recs(raw.message);
    if (!m) fail(`could not read the message: ${aiErrText(raw.message)}`);
    else msg = m.find((r) => r && r.fields && (r.id === Number(st.message_row_id) || (st.wa_message_id && r.fields.WA_Message_ID === st.wa_message_id))) || null;
    if (m && !msg) fail('the message row was not found in Messages');
  }
  const mf = msg ? msg.fields : {};
  const nowSec = Math.floor(nowMs / 1000);
  const ts = msg ? Number(mf.Created_At) || nowSec : nowSec;
  const text = aiClean(msg ? mf.Body : st.text, 2000);

  const convRecs = recs(raw.conversation);
  if (!convRecs) fail(`could not read the conversation: ${aiErrText(raw.conversation)}`);
  const conv = lowest(convRecs);
  if (!dry && convRecs && !conv) fail('the conversation was not found');
  const cf = conv ? conv.fields : {};

  const leadRecs = recs(raw.lead);
  if (!leadRecs) fail(`could not read the lead: ${aiErrText(raw.lead)}`);
  const lead = lowest(leadRecs);
  if (!dry && leadRecs && !lead) fail('the lead was not found');
  const lf = lead ? lead.fields : {};

  const histRecs = recs(raw.history);
  if (!histRecs && conv) notes.push(`conversation history not read (${aiErrText(raw.history)})`);
  const all = histRecs || [];
  const later = (r) => (Number(r.fields.Created_At) || 0) > ts || ((Number(r.fields.Created_At) || 0) === ts && r.id > (msg ? msg.id : 0));
  const others = all.filter((r) => r && r.fields && (!msg || r.id !== msg.id));
  const answeredAfter = !dry && others.some((r) => r.fields.Direction === 'Out' && later(r));
  const newerInbound = !dry && others.some((r) => r.fields.Direction !== 'Out' && later(r));
  const aiRepliesLastHour = others.filter((r) => r.fields.Direction === 'Out' && /^W13/.test(String(r.fields.Sent_By || '')) && (Number(r.fields.Created_At) || 0) >= nowSec - 3600).length;
  // The hand-off a ticked Conversations.Needs_Human waits on = the newest patient message W13 itself marked Needs_Human (handed
  // off or failed). It keeps the AI away from that message and anything older; a patient message written AFTER it is answered
  // again (and can be handed off again). No such message (ticked by hand, or older than the last 40) = the AI stays silent.
  const at = (r) => Number(r.fields.Created_At) || 0;
  const handoffMsg = others.filter((r) => r.fields.Direction !== 'Out' && r.fields.Needs_Human === true).sort((a, b) => at(b) - at(a) || b.id - a.id)[0] || null;
  const afterHandoff = !dry && !!msg && !!handoffMsg && !later(handoffMsg);
  // A staff member's own message (Direction Out, not written by an automation "W<n>-...") in the 24 h before this one.
  const staffMsg = others.find((r) => r.fields.Direction === 'Out' && !/^W\d+(?!\w)/.test(String(r.fields.Sent_By || '').trim()) && !later(r) && at(r) > 0 && at(r) >= ts - AI_STAFF_WINDOW_SEC) || null;
  const staffActive = !dry && !!msg && !!staffMsg;
  const history = aiHistory(others.filter((r) => !later(r)), msg ? msg.id : null, Number(cfg.history_limit) || 12);

  const apptRecs = recs(raw.appointments);
  if (!apptRecs) notes.push(`appointments not read (${aiErrText(raw.appointments)}): no free times offered`);
  const days = Math.min(14, Math.max(2, Number(cfg.slot_days) || 7));
  const slots = apptRecs ? aiFreeSlots(profile, apptRecs, nowMs, days, h) : { known: false, days: [], slot_minutes: profile.slot_minutes, unreadable: true };

  const phone = h.normalizeIndianPhone(lf.Phone || cf.Phone || st.patient_phone).phone;
  const x = {
    now_ms: nowMs,
    dry_run: dry,
    retry: st.w13_retry === true,
    test_case: st.test_case || '',
    calendar: aiCalendar(nowMs, days),
    profile,
    kb,
    slots,
    appointments: apptRecs ? aiLeadAppointments(apptRecs, lead ? lead.id : 0, nowMs) : [],
    appointments_unknown: !apptRecs,
    lead: {
      row_id: lead ? lead.id : 0,
      lead_id: aiLine(lf.Lead_id || lf.Lead_ID || '', 40),
      name: aiLine(lf.Name || st.sender_name || '', 60),
      phone,
      status: aiLine(lf.Status, 20),
      stage: aiLine(lf.Lead_Stage, 10),
      summary: aiLine(lf.AI_Summary, 500),
      enquiry: aiLine(lf.Enquiry, 300),
      created: !history.length,
      opted_out: lf.Opted_Out === true,
      first_response_at: lf.First_Response_At || null,
    },
    history,
    msg: { row_id: msg ? msg.id : 0, wa_message_id: aiLine(mf.WA_Message_ID || st.wa_message_id || `dry-run-${nowMs}`, 120), timestamp: ts, ai_status: aiLine(mf.AI_Status, 20) },
    clinic: { wa_phone_number_id: raw.clinic.wa_phone_number_id, grist_base_url: raw.clinic.grist_base_url, doc_id: raw.clinic.doc_id, name: profile.clinic_name },
    conversation: { row_id: conv ? conv.id : 0 },
    cfg: { reply_mode: dry ? 'auto' : profile.ai_mode, leads_table: cfg.leads_table, min_confidence: cfg.min_confidence, confidence_auto: cfg.confidence_auto, confidence_write: cfg.confidence_write, pause_on_handoff: cfg.pause_on_handoff === true, staff_alert_template: cfg.staff_alert_template },
    text,
    notes,
  };
  const media = /^\[WhatsApp \w+ received\]/.test(text);
  const gate = aiGates({
    failed,
    dry_run: dry,
    retry: x.retry,
    not_inbound: !!msg && mf.Direction === 'Out',
    ai_status: x.msg.ai_status,
    text,
    ai_mode: profile.ai_mode,
    opted_out: x.lead.opted_out,
    paused: cf.Automation_Paused === true,
    needs_human: cf.Needs_Human === true,
    after_handoff: afterHandoff,
    answered_after: answeredAfter,
    newer_inbound: newerInbound,
    staff_active: staffActive,
    night: h.inQuietHours(nowMs) || h.inQuietHours(nowMs + 5 * 60000),
    msg_type: st.msg_type ? String(st.msg_type) : (media ? 'media' : 'text'),   // W2 says the type; a morning retry reads it from the Body
    ai_replies_last_hour: aiRepliesLastHour,
    max_per_hour: Number(cfg.max_ai_replies_per_hour) || 6,
  });
  if (gate.route === 'ai' && cf.Needs_Human === true && afterHandoff) notes.push('new patient message after a hand-off: handled by the AI; Conversations > Needs_Human stays ticked until staff untick it');
  return { x, gate };
}

// ---------------------------------------------------------------- gates that need no AI (first match wins)
// quiet: write nothing at all, not even Run_Log (a message that is not ours, already handled, or AI is off).
function aiGates(c) {
  if (c.failed) return { route: 'failed', reason: c.failed };
  if (!c.dry_run && c.not_inbound) return { route: 'skip', reason: 'not a patient message', quiet: true };
  if (!c.dry_run && c.ai_status && !(c.retry && c.ai_status === 'deferred')) return { route: 'skip', reason: `already handled (AI_Status = ${c.ai_status})`, quiet: true };
  if (AI_STOP_WORDS.test(c.text || '')) return { route: 'opt_out', reason: 'the patient asked us to stop messaging' };
  if (!c.dry_run && c.ai_mode === 'off') return { route: 'skip', reason: 'AI is off for this clinic (Settings ai_mode)', quiet: true };
  if (c.opted_out) return { route: 'skip', reason: 'the lead has opted out' };
  if (c.paused) return { route: 'skip', reason: 'automation is paused for this conversation (staff are handling it)' };
  if (c.needs_human && !c.after_handoff) return { route: 'skip', reason: 'this conversation is waiting for a person and the patient has not written since (untick Conversations > Needs_Human to let the AI answer again)' };
  if (c.answered_after) return { route: 'skip', reason: 'the clinic already answered after this message' };
  if (c.newer_inbound) return { route: 'skip', reason: 'a newer message from this patient is answered instead' };
  const emergency = aiEmergencyIn(c.text);
  if (emergency) {
    return { route: 'handoff', reason: `possible emergency ("${emergency}")`,
      triage: { priority: 'urgent', flags: ['emergency'], note: aiStaffNote(`Possible emergency ("${emergency}"). Patient wrote: "${aiLine(c.text, 120)}". Contact the patient now.`) } };
  }
  if (c.staff_active) return { route: 'skip', reason: 'a staff member is talking to this patient (they wrote in the last 24 h): the AI stays out' };
  if (!c.dry_run && c.night) return { route: 'defer', reason: 'quiet hours (21:00-08:00 IST): answered by the 08:05 run' };
  if (!['text', 'button', 'interactive'].includes(c.msg_type)) return { route: 'handoff', reason: `the patient sent a ${c.msg_type} message; the AI only reads text` };
  if (!aiClean(c.text, 10)) return { route: 'skip', reason: 'empty message' };
  if (c.ai_replies_last_hour >= c.max_per_hour) return { route: 'handoff', reason: `${c.ai_replies_last_hour} automatic replies in the last hour (limit ${c.max_per_hour})` };
  return { route: 'ai', reason: '' };
}

